// Extract incoming webhook payload
const body = $input.item.json.body || $input.item.json;

const caller_name = body.caller_name || '';
const company = body.company || '';
const phone_raw = body.phone || '';
const email = body.email || '';
const pain_point = body.pain_point || '';
const employee_count = parseInt(body.employee_count) || 0;
const budget_indication = body.budget_indication || '';
const decision_maker = body.decision_maker || 'N';
const preferred_call_time = body.preferred_call_time || '';

// Score the lead
let score = 0;
const score_breakdown = [];

if (decision_maker === 'Y') {
  score += 3;
  score_breakdown.push('Decision maker (+3)');
}

if (budget_indication && budget_indication.toLowerCase() !== 'unknown' && budget_indication.trim() !== '') {
  score += 3;
  score_breakdown.push('Budget indicated (+3)');
}

if (employee_count >= 10) {
  score += 2;
  score_breakdown.push('10+ employees (+2)');
}

if (pain_point && pain_point.trim() !== '') {
  score += 2;
  score_breakdown.push('Pain point identified (+2)');
}

// Normalize phone to E.164
let phone = phone_raw.replace(/[^0-9]/g, '');
if (phone.length === 10) {
  phone = '+1' + phone;
} else if (phone.length === 11 && phone.startsWith('1')) {
  phone = '+' + phone;
} else {
  phone = phone_raw;
}

return [{
  json: {
    caller_name,
    company,
    phone,
    phone_raw,
    email,
    pain_point,
    employee_count,
    budget_indication,
    decision_maker,
    preferred_call_time,
    lead_score: score,
    score_breakdown: score_breakdown.join(', '),
    scored_at: new Date().toISOString()
  }
}];

// Determine if contact already exists in HubSpot
const hubspotResult = $input.item.json;
const leadData = $('Calculate Lead Score').item.json;

const existingContactId = (hubspotResult.total > 0 && hubspotResult.results && hubspotResult.results.length > 0)
  ? hubspotResult.results[0].id
  : null;

return [{
  json: {
    ...leadData,
    existing_contact_id: existingContactId,
    contact_exists: existingContactId !== null
  }
}];

