// Merge outputs from all three branches and prepare for note creation
// Collect from whichever branch ran
let contactId = null;
let leadData = $('Calculate Lead Score').item.json;

try {
  const hotContact = $('Create Contact Hot Lead').item;
  if (hotContact && hotContact.json && hotContact.json.id) {
    contactId = hotContact.json.id;
  }
} catch(e) {}

try {
  const medContact = $('Create Contact Medium Lead').item;
  if (medContact && medContact.json && medContact.json.id) {
    contactId = medContact.json.id;
  }
} catch(e) {}

try {
  const lowContact = $('Create Contact Low Lead').item;
  if (lowContact && lowContact.json && lowContact.json.id) {
    contactId = lowContact.json.id;
  }
} catch(e) {}

return [{
  json: {
    ...leadData,
    hubspot_contact_id: contactId
  }
}];

